    private func addWorkbookFiles(_ result: Result<[URL], Error>) async {
        guard case let .success(urls) = result, !urls.isEmpty else { return }
        await MainActor.run { isLoadingWorkbook = true }
        let datas = await Self.loadDownscaledFiles(urls)
        await MainActor.run {
            workbookImages.append(contentsOf: datas)
            isLoadingWorkbook = false
        }
    }

    private func addAnswerFiles(_ result: Result<[URL], Error>) async {
        guard case let .success(urls) = result, !urls.isEmpty else { return }
        await MainActor.run { isLoadingAnswers = true }
        let datas = await Self.loadDownscaledFiles(urls)
        await MainActor.run {
            answerImages.append(contentsOf: datas)
            isLoadingAnswers = false
        }
    }

    /// Load each picked Photos item to Data and downscale it for the request.
    private static func loadDownscaled(_ items: [PhotosPickerItem]) async -> [Data] {
        var datas: [Data] = []
        for item in items {
            if let data = try? await item.loadTransferable(type: Data.self) {
                datas.append(downscaledJPEG(data))
            }
        }
        return datas
    }

    /// Load each user-selected file URL to Data (security-scoped) and downscale.
    private static func loadDownscaledFiles(_ urls: [URL]) async -> [Data] {
        var datas: [Data] = []
        for url in urls {
            let scoped = url.startAccessingSecurityScopedResource()
            defer { if scoped { url.stopAccessingSecurityScopedResource() } }
            if let data = try? Data(contentsOf: url) {
                datas.append(downscaledJPEG(data))
            }
        }
        return datas
    }

    /// Handle images dragged & dropped onto a bucket (Photos, Finder, Safari, …).
    private func handleDrop(_ providers: [NSItemProvider], into target: FileImportTarget) -> Bool {
        let imageProviders = providers.filter { $0.hasItemConformingToTypeIdentifier(UTType.image.identifier) }
        guard !imageProviders.isEmpty else { return false }

        switch target {
        case .workbook: isLoadingWorkbook = true
        case .answers: isLoadingAnswers = true
        }

        Task {
            var datas: [Data] = []
            for provider in imageProviders {
                if let data = await Self.loadImageData(from: provider) {
                    datas.append(downscaledJPEG(data))
                }
            }
            await MainActor.run {
                switch target {
                case .workbook:
                    workbookImages.append(contentsOf: datas)
                    isLoadingWorkbook = false
                case .answers:
                    answerImages.append(contentsOf: datas)
                    isLoadingAnswers = false
                }
            }
        }
        return true
    }

    private static func loadImageData(from provider: NSItemProvider) async -> Data? {
        await withCheckedContinuation { continuation in
            provider.loadDataRepresentation(forTypeIdentifier: UTType.image.identifier) { data, _ in
                continuation.resume(returning: data)
            }
        }
    }

    private func grade() async {
        await MainActor.run {
            isGrading = true
            errorMessage = nil
            result = nil
            savedQuestionIDs = []
            savedToBankIDs = []
            didSaveSession = false
        }
        // Snapshot the inputs (value types are Sendable) for off-main work.
        let wbImages = workbookImages
        let ansImages = answerImages
        let custom = customInstructions
        do {
            let graded = try await AIWordExplanationService.shared.gradeWorkbook(
                workbookImages: wbImages,
                answerImages: ansImages,
                customInstructions: custom.isEmpty ? nil : custom
            )
            // Persist the original scans to disk off the main actor (large IO).
            let (wbIDs, ansIDs) = await Task.detached {
                (WorkbookImageStore.saveAll(wbImages), WorkbookImageStore.saveAll(ansImages))
            }.value
            await MainActor.run {
                // Save this grading as a history session (keeps the photos),
                // and count the graded questions toward today's activity.
                let session = GradedSession(
                    score: graded.score,
                    summary: graded.summary,
                    questions: graded.questions.map { WorkbookQuestion(graded: $0) },
                    workbookImageIDs: wbIDs,
                    answerImageIDs: ansIDs,
                    customInstructions: custom
                )
                WorkbookGradingHistoryStore.shared.add(session)
                if !graded.questions.isEmpty {
                    LearningActivityStore.shared.recordQuestionsGraded(graded.questions.count)
                }
                didSaveSession = true
                result = graded
                isGrading = false
            }
        } catch {
            await MainActor.run {
                errorMessage = error.localizedDescription
                isGrading = false
            }
        }
    }

