            )
            await MainActor.run {
                generated = questions
                revealed = []
                savedIDs = []
                isGenerating = false
                if questions.isEmpty {
                    errorMessage = String(localized: "The model returned no questions. Try again or adjust the instructions.")
                }
            }
        } catch {
            await MainActor.run {
                errorMessage = error.localizedDescription
                isGenerating = false
            }
        }
    }

