    private func addAnswerPhotos(_ items: [PhotosPickerItem]) async {
        await MainActor.run { isLoadingAnswers = true }
        let datas = await Self.loadDownscaled(items)
        await MainActor.run {
            answerImages.append(contentsOf: datas)
            answerItems = []
