.onChange(of: workbookItems) { _, items in
    guard !items.isEmpty else { return }
    Task { await addWorkbookPhotos(items) }
}
.onChange(of: answerItems) { _, items in
    guard !items.isEmpty else { return }
    Task { await addAnswerPhotos(items) }
}

