    private func resultsSection(_ result: GradingResult) -> some View {
        VStack(spacing: 16) {
            // Score header
            HStack {
                VStack(alignment: .leading, spacing: 4) {
                    Text(result.score.isEmpty ? "\(result.correctCount)/\(result.questions.count)" : result.score)
                        .font(.largeTitle)
                        .fontWeight(.bold)
                    Text("正确 \(result.correctCount) · 共 \(result.questions.count) 题")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Image(systemName: "graduationcap.fill")
                    .font(.largeTitle)
                    .foregroundStyle(.tint)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding()
            .background(RoundedRectangle(cornerRadius: 16).fill(.ultraThinMaterial))

            if !result.summary.isEmpty {
                Text(result.summary)
                    .font(.subheadline)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }

            if didSaveSession {
                Label("已保存到批改历史 · Saved to grading history", systemImage: "clock.badge.checkmark")
                    .font(.caption)
                    .foregroundStyle(.secondary)
